SELECT order_id, customer_id, status, amount
FROM orders
WHERE status = 'ACTIVE';

SELECT order_id, amount,
    IIF(amount >= 1000, 1, 0) AS is_high_value
FROM orders;

SELECT customer_id, SUM(amount) AS total_amount
FROM orders
GROUP BY customer_id;

SELECT o.order_id, o.customer_id, o.amount
FROM orders AS o
WHERE NOT EXISTS (
    SELECT 1 FROM customers AS c
    WHERE c.customer_id = o.customer_id
);

WITH x AS (
    SELECT *, LAG(amount) OVER (PARTITION BY customer_id ORDER BY order_date, order_id) AS previous_amount
    FROM orders
)
SELECT customer_id, order_date, order_id, amount, previous_amount, amount - previous_amount AS amount_delta
FROM x;

SELECT order_id, amount FROM historical_orders
UNION ALL
SELECT order_id, amount FROM current_orders;

SELECT employee_name, department, wage,
    DENSE_RANK() OVER (PARTITION BY department ORDER BY wage DESC) AS wage_rank
FROM employees;

SELECT s.size_code, b.brand_name
FROM sizes AS s
CROSS JOIN brands AS b;

SELECT user_id, STRING_AGG(event_name, ',') WITHIN GROUP (ORDER BY event_time DESC) AS recent_events
FROM events
GROUP BY user_id;
